-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.123.0',
  '2026-10-29',
  'Пульт ТВ: переезд сериалов на другой диск прямо из админки',
  E'Когда половина сериалов лежит на одном диске, а половина на другом, в каталоге получаются две плитки с одним названием и вечный вопрос, где какой сезон. Теперь это разбирается, не сходя со страницы: **Админка → Задачи → «📦 Переезд на другой диск»**.\n\nВыбираете, откуда и куда, и дальше либо «Перенести всё», либо по одной папке. **Каждая папка едет отдельной задачей со своей полосой выполнения** — видно, сколько процентов прошло и какой файл идёт прямо сейчас. Едут по одной, остальные ждут очередью: и копирование, и чтение с внешнего диска отбирают силы у самого просмотра. Очередь лежит на диске и переживает перезапуск агента.\n\nПорядок шагов выбран так, чтобы ни на одном нельзя было остаться без файлов: сначала копия в служебную папку на диске-приёмнике, потом сверка (каждый файл есть и ровно того же размера), потом перенос в библиотеку одним движением — сериал появляется целиком, а не по серии, — и только после этого удаляется исходник. Оборвалось или нажали «Остановить» на середине — исходник не тронут, а скопированное останется и в следующий раз догонится, а не поедет заново.\n\nВместе с файлами переезжает и **память медиатеки**: где вы остановились, заставки серий, любимое, подборки, статистика просмотра, постеры и кадры для «Инфо». Без этого переложенный сериал встал бы с начала и без картинки.',
  E'migrate.go: очередь папок на диске (`migrate-queue.json`, как `fetch-queue.json` у ссылок), `migrateWorker` поднимает её, когда агент освободился, каждая папка — своя задача вида `migrate`. Шаги `moveFolder`: `walkFiles` → проверка места (`migrateReserve` 5 ГБ сверх размера) → `copyTree` в `.habits-migrate` рядом с корнем библиотеки-приёмника, но ВНЕ его (внутри каталог показывал бы полусобранные сериалы; `migrateTempDir` проверяет `inRoots` и `sameDisk`) → `verifyTree` по размерам → `os.Rename` (та же ФС, значит мгновенно и неделимо) → `moveMemory` → `RemoveAll` исходника. Докопирование идемпотентно: файл того же размера пропускается, поэтому прерванный переезд продолжается с места. Время правки переносится (`os.Chtimes`): по нему агент решает, не перечитать ли разбор.\n\nГлавное место — `moveMemory(old, neu, isDir)` в admin.go: id объекта это `shortID` = хеш ПУТИ, и переложить файлы, не переписав память, значит осиротить всё. Список вынесен из `renamePath` и общий для переименования и переезда: `remember`, `moveProgress`, `moveMarks`, `moveFrames`, `movePosters` (кэш `posters/<id>.*` и отметки `.miss` — раньше терялись при переименовании), `statsStore.move` (зачёт времени по ключу-плитке — тоже терялся), `colls/favs/links/extras.move` и `agentStore.move`. Последний переписывает кэш ffprobe: `paths`, `probes` и ключи «версия|путь|размер|время правки», пересобранные по факту с диска, — иначе первое открытие папки прогнало бы через ffprobe все 752 серии на внешнем диске.\n\nAPI: `GET /api/admin/migrate [?src=&dst=]` (библиотеки с диском и свободным местом; с `src` — папки с размерами и пометкой занятого имени), `POST /api/admin/migrate {src,dst,names[]}` (пустой `names` — все), `POST /api/admin/migrate/drop {id|all}`. Разные виды библиотек не смешиваются, источник и приёмник не могут совпадать, занятое имя — отказ со строкой в отчёте, а не молчаливое слияние двух раздач.\n\nСтраница: карточка в «Задачах», выбор «откуда»/«куда» чипами (одна библиотека не может быть в двух ролях — выбранная уступает место, а не прячется из списка), список папок читается только на смену выбора и после того, как очередь опустела: мерить папку — это обход всех файлов на внешнем диске, а вкладка обновляется раз в две секунды. У задачи `migrate` полоса и подпись считаются по БАЙТАМ (серии бывают и по 300 МБ, и по 3 ГБ, по числу файлов полоса дёргалась бы рывками).\n\nСемь тестов (`migrate_test.go`): переезд целиком, перенос памяти (прогресс, любимое, статистика, кэш разбора), сверка и сохранность исходника, отказ при занятом имени, докопирование, время правки, очередь через перезапуск агента. Проверено вживую: локальный стенд из двух библиотек через настоящую админку в браузере (очередь из двух сериалов, вторую подхватил воркер сам, постер уехал следом, служебная папка убралась за собой) и на res-i3 — «Misfits», 21 серия, 5 ГБ за 2:08 (40 МБ/с), в кэше ноль старых путей и 21 запись разбора на новом, в каталоге одна плитка с тремя сезонами.'
);
-- +goose StatementEnd

